<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from "vue";
import { browserUuid } from "../../../../../ribiwebgui/src/browserUuid";
import { useVideoCanvas } from "./useVideoCanvas";
import WorkbenchRunPanel from "./WorkbenchRunPanel.vue";
import WorkbenchNodeFields from "./WorkbenchNodeFields.vue";
import WorkbenchCanvasList from "./WorkbenchCanvasList.vue";
import { connectGraph, stageLayout, groupBounds, wirePath, mergePage, NODE_WIDTH, NODE_HEIGHT, type FlowNode, type FlowEdge, type Point, type WorkbenchCanvas, type WorkbenchDefinition } from "./workbenchEditor";
const props = defineProps<{projectId:string}>(),emit = defineEmits<{back:[];media:[canvasId:string]}>();
type Summary={id:string;name:string;revision:number;nodeCount:number};
const project=ref<{title:string;revision:number;defaultCanvasId:string}>(),definition=ref<WorkbenchDefinition>();
const rows=ref<Summary[]>([]),cursor=ref<string|null>(null),search=ref(""),trimmed=ref(0),listLoading=ref(false);
const value=ref<WorkbenchCanvas>(),error=ref(""),busy=ref(false),dirty=ref(false),selected=ref(""),selectedEdge=ref("");
const editor=ref(""),variables=ref("[]"),edgeFrom=ref(""),edgeTo=ref(""),edgeCondition=ref("success"),pastedFolder=ref(""),stageName=ref("");
const conflict=ref(false),recovery=ref<string>(),showAdvanced=ref(false);
const canvas=useVideoCanvas(),{viewport,transform,grid}=canvas;
const base=computed(()=>`/api/video/v2/projects/${encodeURIComponent(props.projectId)}`);
const nodeIndex=computed(()=>new Map(value.value?.graph.nodes.map(node=>[node.id,node])||[]));
const activeNode=computed(()=>nodeIndex.value.get(selected.value));
const activeEdge=computed(()=>value.value?.graph.edges.find(edge=>edge.id===selectedEdge.value));
const parsedNode=computed(()=>{try{const parsed=JSON.parse(editor.value);return parsed&&parsed.config&&typeof parsed.config==="object"&&!Array.isArray(parsed.config)?parsed:undefined;}catch{return undefined;}});
const stages=computed(()=>value.value?.graph.groups.map(group=>({...group,bounds:groupBounds(group,canvas.positions.value)})).filter(group=>group.bounds)||[]);
const activeStage=computed(()=>value.value?.graph.groups.find(group=>group.nodeIds.includes(selected.value))?.id||"");
const curves=computed(()=>value.value?.graph.edges.map(edge=>({...edge,path:wirePath(portPoint(edge.from,"out",edge.fromPort),portPoint(edge.to,"in",edge.toPort))}))||[]);
const wire=ref<{node:string;port:string;point:Point;pointer?:number}>();
const previewPath=computed(()=>wire.value?wirePath(portPoint(wire.value.node,"out",wire.value.port),wire.value.point):"");
let disposed=false,actionId=0,openId=0,listId=0,initId=0;
let openController:AbortController|undefined,listController:AbortController|undefined;
let listFlight:{key:string;promise:Promise<void>}|undefined,saveFlight:Promise<void>|undefined;
const draftKey=(projectId:string,id:string)=>`workbench-draft:${projectId}:${id}`;
class RequestError extends Error{constructor(message:string,readonly status:number){super(message);}}
async function api<T>(suffix:string,method="GET",body?:unknown,options:{root?:string;signal?:AbortSignal}={}):Promise<T>{
  const response=await fetch((options.root||base.value)+suffix,{method,headers:{"content-type":"application/json"},signal:options.signal,...(body===undefined?{}:{body:JSON.stringify(body)})});
  const result=await response.json();if(!response.ok)throw new RequestError(result.message||"工作台请求失败。",response.status);return result;
}
async function action(fn:()=>Promise<unknown>){if(busy.value||disposed)return;const token=++actionId;busy.value=true;error.value="";try{await fn();}catch(cause){if(token===actionId&&!disposed&&!(cause instanceof Error&&cause.name==="AbortError"))error.value=cause instanceof Error?cause.message:String(cause);}finally{if(token===actionId&&!disposed)busy.value=false;}}
function route(id?:string){const url=new URL(location.href);if(id){if(url.searchParams.get("canvas")!==id)url.searchParams.delete("run");url.searchParams.set("canvas",id);url.searchParams.delete("view");}else{url.searchParams.delete("run");url.searchParams.delete("canvas");url.searchParams.set("view","canvases");}history.replaceState(null,"",url);}
async function list(append=false){
  const root=base.value,term=search.value,after=append?cursor.value:null,key=JSON.stringify([root,term,after]);
  if(listFlight?.key===key)return listFlight.promise;
  if(append&&!after)return;
  const token=++listId;listController?.abort();const controller=new AbortController();listController=controller;listLoading.value=true;
  const query=new URLSearchParams({limit:"50",search:term});if(after)query.set("cursor",after);
  const operation=(async()=>{const page=await api<{canvases:Summary[];nextCursor:string|null}>(`/canvases?${query}`,"GET",undefined,{root,signal:controller.signal});
    if(disposed||token!==listId||root!==base.value||term!==search.value)return;
    if(append){const merged=mergePage(rows.value,page.canvases);rows.value=merged.rows;trimmed.value+=merged.removed;}
    else{rows.value=page.canvases;trimmed.value=0;}cursor.value=page.nextCursor;
  })();
  listFlight={key,promise:operation};try{await operation;}finally{if(token===listId){listLoading.value=false;listFlight=undefined;}}
}
function rememberDraft(projectId=props.projectId){if(!value.value||!dirty.value)return;try{const key=draftKey(projectId,value.value.id),keys=JSON.parse(sessionStorage.getItem("workbench-draft-keys")||"[]").filter((entry:string)=>entry!==key);keys.push(key);while(keys.length>8)sessionStorage.removeItem(keys.shift());sessionStorage.setItem(key,draftSnapshot());sessionStorage.setItem("workbench-draft-keys",JSON.stringify(keys));}catch{}}
function forgetDraft(projectId=props.projectId,id=value.value?.id){if(id)try{sessionStorage.removeItem(draftKey(projectId,id));}catch{}}
function restoreDraft(){if(!recovery.value)return;const [record,text,vars,positions,nodeId]=JSON.parse(recovery.value);value.value=record;editor.value=text;variables.value=vars;canvas.positions.value=positions;selected.value=nodeId||"";dirty.value=true;recovery.value=undefined;}
async function open(id:string,runId?:string){
  if(dirty.value)throw new Error("当前画布尚未保存。请保存或导出草稿后再切换。");
  const root=base.value,token=++openId;openController?.abort();const controller=new AbortController();openController=controller;
  const record=await api<WorkbenchCanvas>(`/canvases/${encodeURIComponent(id)}`,"GET",undefined,{root,signal:controller.signal});
  if(disposed||token!==openId||root!==base.value)return;
  if(dirty.value)throw new Error("打开期间产生了新编辑，已保留当前画布。");
  value.value=record;selected.value="";selectedEdge.value="";editor.value="";variables.value=JSON.stringify(record.variables,null,2);conflict.value=false;wire.value=undefined;
  canvas.positions.value=Object.fromEntries(record.graph.nodes.map(node=>[node.id,node.layout||{x:0,y:0}]));
  try{recovery.value=sessionStorage.getItem(draftKey(props.projectId,id))||undefined;}catch{recovery.value=undefined;}
  route(id);if(runId){const url=new URL(location.href);url.searchParams.set("run",runId);history.replaceState(null,"",url);}await nextTick();if(token===openId)fitGraph();
}
async function create(){const root=base.value,record=await api<WorkbenchCanvas>("/canvases","POST",{id:browserUuid()},{root});if(root===base.value&&!disposed)await open(record.id);}
async function importFile(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value="";if(!file)return;if(file.size>64*1024*1024-4096)throw new Error("导入定义或材料包最大 64 MB。");const root=base.value,parsed=JSON.parse(await file.text()),packet=parsed&&typeof parsed==="object"&&Object.hasOwn(parsed,"source")&&!parsed.graph&&!parsed.nodes,body={id:browserUuid(),source:packet?parsed.source:parsed,...(packet&&parsed.materials!==undefined?{materials:parsed.materials}:{})};if(root!==base.value)return;const record=await api<WorkbenchCanvas>("/canvases/import","POST",body,{root});if(root===base.value&&!disposed)await open(record.id);}
function parseDraft(text:string,label:string){try{return JSON.parse(text);}catch{throw new Error(`${label} JSON 无效，请修正后重试。当前草稿已保留。`);}}
function applyNode(){const node=activeNode.value;if(!node)return;const parsed=parseDraft(editor.value,"节点参数");if(!parsed||!parsed.config||typeof parsed.config!=="object"||Array.isArray(parsed.config))throw new Error("节点参数需要 config 对象。当前草稿已保留。");if(parsed.inputs!==undefined&&!Array.isArray(parsed.inputs)||parsed.requirements!==undefined&&!Array.isArray(parsed.requirements))throw new Error("输入与产物要求需要数组。当前草稿已保留。");if(JSON.stringify(parsed)===JSON.stringify({config:node.config,inputs:node.inputs||[],requirements:node.requirements||[]}))return;node.config=parsed.config;node.inputs=parsed.inputs;node.requirements=parsed.requirements;dirty.value=true;}
function select(node:FlowNode){if(selected.value===node.id)return;applyNode();selected.value=node.id;selectedEdge.value="";editor.value=JSON.stringify({config:node.config,inputs:node.inputs||[],requirements:node.requirements||[]},null,2);}
function updateConfig(config:Record<string,unknown>){if(!parsedNode.value)return;editor.value=JSON.stringify({...parsedNode.value,config},null,2);dirty.value=true;}
function updateRows(kind:"inputs"|"requirements",index:number,key:string,next:unknown){if(!parsedNode.value)return;const parsed=JSON.parse(editor.value),rows=parsed[kind]||[];rows[index]={...rows[index],[key]:next};editor.value=JSON.stringify({...parsed,[kind]:rows},null,2);dirty.value=true;}
function updateRef(index:number,key:string,next:string){const current=parsedNode.value?.inputs?.[index]?.ref||{};updateRows("inputs",index,"ref",{...current,[key]:next});}
function addRow(kind:"inputs"|"requirements"){if(!parsedNode.value)return;const parsed=JSON.parse(editor.value),rows=parsed[kind]||[];rows.push(kind==="inputs"?{ref:{root:"canvas",path:""}}:{key:`output-${rows.length+1}`,root:"output",path:"",type:"file",required:true,freshness:"produced"});editor.value=JSON.stringify({...parsed,[kind]:rows},null,2);dirty.value=true;}
function removeRow(kind:"inputs"|"requirements",index:number){if(!parsedNode.value)return;const parsed=JSON.parse(editor.value);parsed[kind].splice(index,1);editor.value=JSON.stringify(parsed,null,2);dirty.value=true;}
function add(kind:string){if(!value.value)return;applyNode();const id=browserUuid();canvas.add(id);const config=kind==="command"?{toolKey:"",argv:[]}:kind==="agent"?{target:{},source:{},briefRef:{root:"canvas",path:""}}:kind==="generate"?{command:{}}:kind==="asset"?{mediaKind:"text",ref:{root:"canvas",path:""}}:{};const node={id,kind,title:definition.value?.capabilities[kind]?.label||kind,enabled:true,config,layout:canvas.positions.value[id]};value.value.graph.nodes.push(node);select(node);dirty.value=true;}
function connect(from=edgeFrom.value,to=edgeTo.value,fromPort="control",toPort="control"){if(!value.value||!definition.value)return;applyNode();const edge=connectGraph(value.value.graph,definition.value,{id:browserUuid(),from,to,fromPort,toPort,condition:edgeCondition.value});value.value.graph.edges.push(edge);selectedEdge.value=edge.id;dirty.value=true;}
function remove(){if(!value.value)return;const id=selected.value,graph=value.value.graph;graph.nodes=graph.nodes.filter(node=>node.id!==id);graph.edges=graph.edges.filter(edge=>edge.from!==id&&edge.to!==id);for(const group of graph.groups)group.nodeIds=group.nodeIds.filter(nodeId=>nodeId!==id);delete canvas.positions.value[id];selected.value="";editor.value="";dirty.value=true;}
function removeEdge(id:string){if(!value.value)return;value.value.graph.edges=value.value.graph.edges.filter(edge=>edge.id!==id);selectedEdge.value="";dirty.value=true;}
function assignStage(id:string){if(!value.value||!activeNode.value)return;for(const group of value.value.graph.groups)group.nodeIds=group.nodeIds.filter(nodeId=>nodeId!==selected.value);value.value.graph.groups.find(group=>group.id===id)?.nodeIds.push(selected.value);dirty.value=true;}
function createStage(){if(!value.value||!stageName.value.trim())return;value.value.graph.groups.push({id:browserUuid(),name:stageName.value.trim(),nodeIds:[]});stageName.value="";dirty.value=true;}
function autoLayout(){if(!value.value||!definition.value)return;applyNode();canvas.positions.value=stageLayout(value.value.graph,definition.value);dirty.value=true;nextTick(fitGraph);}
function focusBounds(bounds:{x:number;y:number;width:number;height:number}){const element=viewport.value;if(!element)return;canvas.scale.value=Math.max(.25,Math.min(1,(element.clientWidth-100)/bounds.width,(element.clientHeight-100)/bounds.height));canvas.offset.value={x:(element.clientWidth-bounds.width*canvas.scale.value)/2-bounds.x*canvas.scale.value,y:(element.clientHeight-bounds.height*canvas.scale.value)/2-bounds.y*canvas.scale.value};}
function fitGraph(){const points=Object.values(canvas.positions.value);if(!points.length)return;const x=Math.min(...points.map(p=>p.x))-40,y=Math.min(...points.map(p=>p.y))-70;focusBounds({x,y,width:Math.max(...points.map(p=>p.x))+NODE_WIDTH+40-x,height:Math.max(...points.map(p=>p.y))+NODE_HEIGHT+40-y});}
function draftPayload(){applyNode();const payload=JSON.parse(JSON.stringify(value.value)) as WorkbenchCanvas;payload.variables=parseDraft(variables.value,"变量");for(const node of payload.graph.nodes)node.layout=canvas.positions.value[node.id]||node.layout;return payload;}
function draftSnapshot(){return JSON.stringify([value.value,editor.value,variables.value,canvas.positions.value,selected.value]);}
async function save(){if(saveFlight)return saveFlight;if(!value.value)return;const current=value.value,root=base.value,projectId=props.projectId,payload=draftPayload(),submitted=draftSnapshot();
  const operation=(async()=>{try{const saved=await api<WorkbenchCanvas>(`/canvases/${payload.id}`,"PUT",payload,{root});if(disposed||root!==base.value||value.value!==current)return;if(draftSnapshot()===submitted){value.value=saved;dirty.value=false;forgetDraft(projectId,payload.id);}else{value.value.revision=saved.revision;dirty.value=true;}conflict.value=false;}catch(cause){if(root===base.value&&value.value===current&&cause instanceof RequestError&&cause.status===409){conflict.value=true;rememberDraft();}throw cause;}})();saveFlight=operation;try{await operation;}finally{if(saveFlight===operation)saveFlight=undefined;}}
async function reloadServer(){if(!value.value)return;const id=value.value.id,wasDirty=dirty.value;dirty.value=false;try{await open(id);forgetDraft();recovery.value=undefined;}catch(cause){dirty.value=wasDirty;throw cause;}}
async function showList(){if(dirty.value)throw new Error("当前画布尚未保存。请保存或导出草稿后再切换。");++openId;openController?.abort();value.value=undefined;selected.value="";rows.value=[];route();await list();}
async function copy(row:{id:string;name:string}){const root=base.value,copied=await api<WorkbenchCanvas>("/canvases/copy","POST",{id:browserUuid(),requestId:browserUuid(),sourceCanvasId:row.id,name:`${row.name} 副本`},{root});if(root===base.value&&!disposed)await open(copied.id);}
async function registerFolder(){const root=base.value,record=await api<WorkbenchCanvas>("/canvases/copy","POST",{id:browserUuid(),requestId:browserUuid(),folderName:pastedFolder.value},{root});if(root===base.value&&!disposed)await open(record.id);}
async function setDefault(){if(!value.value||!project.value)return;const root=base.value,record=await api<typeof project.value>("","PUT",{revision:project.value.revision,defaultCanvasId:value.value.id},{root});if(root===base.value&&!disposed)project.value=record;}
async function exportDraft(){if(!value.value)return;const blob=new Blob([JSON.stringify(draftPayload(),null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download=`${value.value.id}.json`;link.click();URL.revokeObjectURL(url);}
function ports(node:FlowNode,direction:"in"|"out"){return definition.value?.capabilities[node.kind]?.ports?.[direction]||[];}
function portPoint(id:string,direction:"in"|"out",port:string){const point=canvas.positions.value[id]||{x:0,y:0},node=nodeIndex.value.get(id),index=node?Math.max(0,ports(node,direction).indexOf(port)):0;return {x:point.x+(direction==="out"?NODE_WIDTH:0),y:point.y+86+index*24};}
function beginWire(event:PointerEvent,node:FlowNode,port:string){if(event.button!==0)return;event.preventDefault();wire.value={node:node.id,port,point:portPoint(node.id,"out",port),pointer:event.pointerId};viewport.value?.setPointerCapture(event.pointerId);}
function armWire(node:FlowNode,port:string){wire.value={node:node.id,port,point:portPoint(node.id,"out",port)};}
function keyboardWire(event:MouseEvent,node:FlowNode,port:string){if(event.detail===0)armWire(node,port);}
function finishWire(node:string,port:string){const current=wire.value;wire.value=undefined;if(current)connect(current.node,node,current.port,port);}
function movePointer(event:PointerEvent){if(!wire.value){canvas.move(event);return;}const bounds=viewport.value?.getBoundingClientRect();if(bounds)wire.value.point=canvas.world({x:event.clientX-bounds.left,y:event.clientY-bounds.top});}
function finishGesture(event:PointerEvent){if(wire.value?.pointer!==undefined){const current=wire.value;if(current.pointer!==event.pointerId)return;if(viewport.value?.hasPointerCapture(event.pointerId))viewport.value.releasePointerCapture(event.pointerId);const target=document.elementFromPoint(event.clientX,event.clientY)?.closest<HTMLElement>('[data-port-direction="in"]');if(target)void action(async()=>finishWire(target.dataset.nodeId!,target.dataset.port!));else wire.value=undefined;return;}canvas.end(event);if(value.value?.graph.nodes.some(node=>JSON.stringify(node.layout||{x:0,y:0})!==JSON.stringify(canvas.positions.value[node.id]||{x:0,y:0})))dirty.value=true;}
function cancelPointer(event:PointerEvent){wire.value=undefined;canvas.end(event);if(viewport.value?.hasPointerCapture(event.pointerId))viewport.value.releasePointerCapture(event.pointerId);}
function backgroundPointer(event:PointerEvent){if(wire.value||(event.target as Element).closest('.canvas-object,.edge-path'))return;canvas.begin(event);}
function startNodeDrag(event:PointerEvent,node:FlowNode){if(busy.value||wire.value)return;void action(async()=>select(node));canvas.selectedIds.value=[node.id];canvas.begin(event,node.id);}
function protect(event:BeforeUnloadEvent){if(dirty.value){rememberDraft();event.preventDefault();event.returnValue="";}}
async function initialize(){const token=++initId,root=base.value;const [entry,record]=await Promise.all([fetch("/api/video/v2/definition").then(async response=>{if(!response.ok)throw new Error("无法读取节点定义。");return response.json();}),api<typeof project.value>("","GET",undefined,{root})]);if(disposed||token!==initId||root!==base.value)return;definition.value=entry;project.value=record;const params=new URL(location.href).searchParams;if(params.get("view")==="canvases")await list();else if(record)await open(params.get("canvas")||record.defaultCanvasId);}
watch(()=>props.projectId,(_next,previous)=>{rememberDraft(previous);++actionId;++openId;++listId;++initId;openController?.abort();listController?.abort();busy.value=false;saveFlight=undefined;listFlight=undefined;value.value=undefined;project.value=undefined;dirty.value=false;selected.value="";editor.value="";rows.value=[];cursor.value=null;wire.value=undefined;recovery.value=undefined;void action(initialize);});
onMounted(()=>{void action(initialize);window.addEventListener("beforeunload",protect);});
onBeforeUnmount(()=>{rememberDraft();disposed=true;++openId;++listId;++initId;++actionId;openController?.abort();listController?.abort();window.removeEventListener("beforeunload",protect);});
</script>
<template>
  <section class="workbench">
    <header class="workbench-header"><v-btn variant="text" @click="value?action(showList):emit('back')">{{value?'画布列表':'我的项目'}}</v-btn><div class="project-heading"><small>工作台</small><strong>{{project?.title}}</strong></div><input v-if="value" v-model="value.name" aria-label="画布名称" @input="dirty=true"/><span v-if="dirty" class="save-state">未保存</span><v-spacer/><template v-if="value"><v-btn :disabled="busy" variant="text" @click="action(exportDraft)">导出定义</v-btn><v-btn :disabled="busy" variant="text" @click="action(setDefault)">设为默认</v-btn><v-btn :disabled="busy||dirty" @click="emit('media',value.id)">媒体编辑</v-btn><v-btn :disabled="busy" color="primary" @click="action(save)">保存画布</v-btn></template><v-btn v-else :disabled="busy" color="primary" @click="action(create)">新建画布</v-btn></header>
    <v-alert v-if="error&&!conflict" type="error" variant="tonal">{{error}}</v-alert>
    <v-alert v-if="conflict" type="warning" variant="tonal">服务器版本已更新，本地编辑已保留。<div class="notice-actions"><v-btn @click="action(exportDraft)">导出本地草稿</v-btn><v-btn variant="text" @click="action(reloadServer)">放弃本地编辑，重载服务器版本</v-btn></div></v-alert>
    <v-alert v-if="recovery" type="warning" variant="tonal">此画布有未保存的草稿。<v-btn @click="restoreDraft">恢复草稿</v-btn><v-btn variant="text" @click="forgetDraft();recovery=undefined">忽略草稿</v-btn></v-alert>
    <details v-if="value?.importReport" class="report"><summary>导入报告</summary><pre>{{JSON.stringify(value.importReport,null,2)}}</pre></details>
    <details v-if="value?.externalDependencies" class="report"><summary>外部依赖</summary><pre>{{JSON.stringify(value.externalDependencies,null,2)}}</pre></details>
    <template v-if="!value"><div class="list-tools"><div><h2>画布</h2></div><v-spacer/><input v-model="search" type="search" aria-label="搜索画布" placeholder="搜索画布" @keyup.enter="action(()=>list())"/><v-btn :disabled="listLoading" @click="action(()=>list())">搜索</v-btn></div><WorkbenchCanvasList :rows="rows" :disabled="busy" @open="id=>action(()=>open(id))" @copy="row=>action(()=>copy(row))"/><div class="list-footer"><small>{{trimmed?`当前保留第 ${trimmed+1}–${trimmed+rows.length} 项`:`已加载 ${rows.length} 张画布`}}</small><v-btn v-if="trimmed" variant="text" :disabled="listLoading" @click="action(()=>list())">返回首页</v-btn><v-btn v-if="cursor" :disabled="listLoading||busy" @click="action(()=>list(true))">{{listLoading?'加载中…':'加载下一页'}}</v-btn></div><details class="import-tools"><summary>导入与文件夹副本</summary><label>导入定义或材料包<input type="file" accept="application/json,.json" :disabled="busy" @change="event=>action(()=>importFile(event))"/></label><div class="list-tools"><input v-model="pastedFolder" aria-label="已粘贴的文件夹名" placeholder="已粘贴到 canvases/ 的文件夹名"/><v-btn :disabled="!pastedFolder||busy" @click="action(registerFolder)">登记副本</v-btn></div></details></template>
    <template v-else><nav class="graph-toolbar"><v-btn size="small" variant="text" @click="action(async()=>autoLayout())">按阶段排列</v-btn><v-btn size="small" variant="text" @click="fitGraph">显示全部</v-btn><v-btn size="small" variant="text" @click="canvas.zoom(canvas.scale.value/1.2)">−</v-btn><span>{{Math.round(canvas.scale.value*100)}}%</span><v-btn size="small" variant="text" @click="canvas.zoom(canvas.scale.value*1.2)">＋</v-btn><button v-for="stage in stages" :key="stage.id" class="stage-shortcut" @click="focusBounds(stage.bounds!)">{{stage.name||'未命名阶段'}} <small>{{stage.nodeIds.length}}</small></button><span v-if="wire" class="wire-hint">选择输入端口 · Esc 取消</span></nav>
      <div class="editor-layout">
        <aside class="tool-rail"><h3>画布设置</h3><label>执行目录绑定<input v-model="value.workspaceBindingKey" @input="dirty=true"/></label><details><summary>变量</summary><textarea v-model="variables" rows="6" aria-label="画布变量 JSON" @input="dirty=true"/></details><h3>添加节点</h3><div class="node-palette"><button v-for="(entry,kind) in definition?.capabilities" :key="kind" @click="action(async()=>add(String(kind)))"><span aria-hidden="true">＋</span>{{entry.label}}</button></div><h3>阶段</h3><div class="stage-form"><input v-model="stageName" aria-label="新阶段名称" placeholder="阶段名称"/><button :disabled="!stageName.trim()" aria-label="添加阶段" @click="createStage">＋</button></div><p v-if="!value.graph.groups.length" class="muted">尚未分组</p><button v-for="stage in value.graph.groups" :key="stage.id" class="stage-item" :disabled="!stages.find(row=>row.id===stage.id)" @click="focusBounds(stages.find(row=>row.id===stage.id)!.bounds!)">{{stage.name||'未命名阶段'}}<small>{{stage.nodeIds.length}}</small></button><details class="connection-tools"><summary>键盘连接</summary><select v-model="edgeFrom" aria-label="前置节点"><option value="">选择前置</option><option v-for="node in value.graph.nodes.filter(n=>ports(n,'out').length)" :key="node.id" :value="node.id">{{node.title}}</option></select><select v-model="edgeTo" aria-label="后继节点"><option value="">选择后继</option><option v-for="node in value.graph.nodes.filter(n=>ports(n,'in').length)" :key="node.id" :value="node.id">{{node.title}}</option></select><select v-model="edgeCondition" aria-label="连接条件"><option value="success">成功后</option><option value="completed">结束后</option></select><v-btn :disabled="!edgeFrom||!edgeTo" @click="action(async()=>connect())">连接</v-btn></details></aside>
        <div ref="viewport" class="graph-viewport" tabindex="0" aria-label="工作流画布" :style="grid" @keydown.esc="wire=undefined" @pointerdown="backgroundPointer" @pointermove="movePointer" @pointerup="finishGesture" @pointercancel="cancelPointer" @wheel.prevent="canvas.wheel"><div class="graph-world" :style="transform"><div v-for="stage in stages" :key="stage.id" class="stage-frame" :style="{left:stage.bounds!.x+'px',top:stage.bounds!.y+'px',width:stage.bounds!.width+'px',height:stage.bounds!.height+'px'}"><span>{{stage.name||'未命名阶段'}}<small>{{stage.nodeIds.length}} 个节点</small></span></div><svg class="edges"><defs><marker id="workbench-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#719f9c"/></marker></defs><path v-for="edge in curves" :key="edge.id" class="edge-path" marker-end="url(#workbench-arrow)" :class="{active:edge.id===selectedEdge,completed:edge.condition==='completed'}" :d="edge.path" @click.stop="selectedEdge=edge.id"/><path v-if="wire" class="preview-wire" :d="previewPath"/></svg><article v-for="node in value.graph.nodes" :key="node.id" class="canvas-object flow-node" :class="{selected:node.id===selected,disabled:node.enabled===false}" :style="canvas.position(node.id)" @click.stop="action(async()=>select(node))"><header @pointerdown.stop="startNodeDrag($event,node)"><span>{{definition?.capabilities[node.kind]?.label}}<small v-if="node.gate">门禁</small></span><strong>{{node.title}}</strong></header><footer><span>{{node.enabled===false?'已禁用':'已启用'}}</span><span v-if="node.config.unresolved" class="unresolved">待配置</span><span v-else-if="node.requirements?.length">{{node.requirements.length}} 项产物检查</span></footer><button v-for="(port,index) in ports(node,'in')" :key="'in-'+port" class="port input-port" :style="{top:76+index*24+'px'}" data-port-direction="in" :data-node-id="node.id" :data-port="port" :aria-label="`连接到 ${node.title} 的 ${port} 输入`" @pointerdown.stop @click.stop="action(async()=>finishWire(node.id,port))"/><button v-for="(port,index) in ports(node,'out')" :key="'out-'+port" class="port output-port" :style="{top:76+index*24+'px'}" :aria-label="`从 ${node.title} 的 ${port} 输出连线`" @pointerdown.stop="beginWire($event,node,port)" @click.stop="keyboardWire($event,node,port)"/></article></div><div v-if="!value.graph.nodes.length" class="empty-graph">从左侧添加第一个节点</div></div>
        <aside v-if="activeNode" class="inspector"><h3>节点参数</h3><label>节点名称<input v-model="activeNode.title" @input="dirty=true"/></label><label>所属阶段<select :value="activeStage" @change="assignStage(($event.target as HTMLSelectElement).value)"><option value="">未分组</option><option v-for="stage in value.graph.groups" :key="stage.id" :value="stage.id">{{stage.name}}</option></select></label><div class="node-flags"><label><input :checked="activeNode.enabled!==false" type="checkbox" @change="activeNode.enabled=($event.target as HTMLInputElement).checked;dirty=true"/>启用</label><label><input v-model="activeNode.gate" type="checkbox" @change="dirty=true"/>门禁</label><label><input v-model="activeNode.optional" type="checkbox" @change="dirty=true"/>可选</label></div><WorkbenchNodeFields v-if="parsedNode" :kind="activeNode.kind" :model-value="parsedNode.config" @update:model-value="updateConfig"/><p v-else class="muted">高级 JSON 无效，修正后可使用表单。</p><details v-if="parsedNode" class="artifact-form"><summary>输入材料（{{parsedNode.inputs?.length||0}}）</summary><div v-for="(input,index) in parsedNode.inputs||[]" :key="index" class="requirement-row"><template v-if="input.producerNodeId"><label>前置节点<select :value="input.producerNodeId" @change="updateRows('inputs',index,'producerNodeId',($event.target as HTMLSelectElement).value)"><option v-for="node in value.graph.nodes.filter(node=>node.id!==selected)" :key="node.id" :value="node.id">{{node.title}}</option></select></label><label>产物名称<input :value="input.artifactKey" @input="updateRows('inputs',index,'artifactKey',($event.target as HTMLInputElement).value)"/></label></template><template v-else><label>位置<select :value="input.ref?.root" @change="updateRef(index,'root',($event.target as HTMLSelectElement).value)"><option v-for="root in ['canvas','materials','output','runtime']" :key="root">{{root}}</option></select></label><label>相对路径<input :value="input.ref?.path" @input="updateRef(index,'path',($event.target as HTMLInputElement).value)"/></label></template><button class="text-danger" @click="removeRow('inputs',index)">移除输入</button></div><button class="add-row" @click="addRow('inputs')">＋ 添加材料输入</button></details><details v-if="parsedNode" class="artifact-form"><summary>产物检查（{{parsedNode.requirements?.length||0}}）</summary><div v-for="(item,index) in parsedNode.requirements||[]" :key="index" class="requirement-row"><label>产物名称<input :value="item.key" @input="updateRows('requirements',index,'key',($event.target as HTMLInputElement).value)"/></label><label>位置<select :value="item.root" @change="updateRows('requirements',index,'root',($event.target as HTMLSelectElement).value)"><option v-for="root in ['output','canvas','materials','runtime']" :key="root">{{root}}</option></select></label><label>相对路径<input :value="item.path" @input="updateRows('requirements',index,'path',($event.target as HTMLInputElement).value)"/></label><label>检查方式<select :value="item.freshness" @change="updateRows('requirements',index,'freshness',($event.target as HTMLSelectElement).value)"><option value="produced">本次生成</option><option value="validated">本次核验</option><option value="reused">复用原产物</option></select></label><button class="text-danger" @click="removeRow('requirements',index)">移除检查</button></div><button class="add-row" @click="addRow('requirements')">＋ 添加产物检查</button></details><details :open="showAdvanced" class="advanced-editor"><summary @click="showAdvanced=!showAdvanced">高级 JSON</summary><label>参数、输入与产物要求<textarea v-model="editor" rows="16" spellcheck="false" @input="dirty=true"/></label></details><v-btn size="small" variant="tonal" @click="action(async()=>applyNode())">应用参数</v-btn><v-btn size="small" color="error" variant="text" @click="remove">移除节点</v-btn></aside>
      </div><div v-if="activeEdge" class="edge-inspector"><strong>{{nodeIndex.get(activeEdge.from)?.title}} → {{nodeIndex.get(activeEdge.to)?.title}}</strong><label>触发条件<select v-model="activeEdge.condition" @change="if(activeEdge.condition!=='completed')delete activeEdge.allowSkip;dirty=true"><option value="success">前置成功后</option><option value="completed">前置结束后</option></select></label><label v-if="activeEdge.condition==='completed'&&nodeIndex.get(activeEdge.from)?.optional"><input v-model="activeEdge.allowSkip" type="checkbox" @change="dirty=true"/>允许前置跳过</label><button class="text-danger" @click="removeEdge(activeEdge.id)">移除连接</button></div>
      <WorkbenchRunPanel :key="projectId+':'+value.id" :project-id="projectId" :canvas-id="value.id" :revision="value.revision" :dirty="dirty||busy" :states="definition?.nodeStates" :run-states="definition?.runStates" @edition="(canvasId,runId)=>action(()=>open(canvasId,runId))"/>
    </template>
  </section>
</template>
